BASE=Path(__file__).resolve().parents[1];OUT=BASE/'.cache/batch200/drafts/rewrite_vid'
def S(w):return 'https://www.etymonline.com/word/'+w
def K(w):return 'https://en.wiktionary.org/wiki/'+w
def O(w):return 'https://www.oxfordlearnersdictionaries.com/definition/english/'+w
G=[['拉丁 magnus','大、伟大、有分量'],['拉丁 magnus + facere 的构词形式 → magnificus','做大事的、高贵的、壮丽的']]
AD=G+[['拉丁 magnificent-；比较级 magnificentior','magnificus 家族中的词干形式'],['古法语 magnificent → 中古英语 magnificent','卓越、壮丽、令人赞叹']]
V=G+[['拉丁 magnificare → 古法语 magnefiier／magnifier','看重、赞颂、使显得伟大'],['中古英语 magnifien → magnify','赞颂；后来也指放大图像、夸大程度']]
W=[
E('magnificent','英、美 /mæɡˈnɪfɪsənt/','壮丽的；华美的；极出色的','看到雄伟的建筑、开阔的景色，或精彩的表现，会由衷觉得“真了不起”。它赞的是气势或品质，不只量尺寸。','远接拉丁 magnus“大”与 facere“做”构成的 magnificus；经 magnificent- 一类词干和法语 magnificent 进入英语。词干也见于比较级 magnificentior，不能把现代英语机械拆成一个独立的 ficent 单词。',AD,'a magnificent building 可以是建筑很壮丽；a magnificent performance 则是表现极出色，即使舞台很小。它的“大”早已能说成就、气魄和令人赞叹的程度。','a magnificent view；a magnificent achievement；a magnificent performance。','huge 主要说体积或数量大；magnificent 是强烈赞美。很大的建筑也可以丑陋，壮丽的景色却不必昂贵。',('The train rounded a bend, revealing a magnificent mountain view.','火车转过弯，壮丽的山景展现在眼前。'),('She gave a magnificent performance in the final scene.','她在最后一幕中的表演极为出色。'),sources=[S('magnificent'),K('magnificent'),O('magnificent')]),
E('magnificently','英、美 /mæɡˈnɪfɪsəntli/','壮丽地；华丽地；极出色地','把赞叹放到动作或状态上：建筑装饰得华美，队员表现得出色，景物铺展开来很壮观。','中古英语已有 magnyficently 一类形式，对应 magnificent 家族加副词 -ly。现代可直接按 magnificent + -ly 理解；早期拼写与记载并不要求先有今日标准形容词拼写才有副词。',[['拉丁 magnificus／magnificent- → 法语、英语 magnificent 家族','壮丽、卓越的意义进入英语'],['中古英语 magnyficently → magnificently','形容词家族与 -ly 结合的副词']],'magnificently decorated 说装饰得华美；performed magnificently 说表现非常出色。副词不必描写可见的大东西，也能评价组织、演奏或应对困难的能力。','magnificently decorated；perform magnificently；rise magnificently above。','beautifully 偏向美或做得优美；magnificently 往往多一层气派、力度或强烈赞叹。',('The hall was magnificently decorated for the festival.','节日期间，大厅装饰得华丽壮观。'),('The young goalkeeper performed magnificently under pressure.','这位年轻门将在压力下表现得极为出色。'),sources=[S('magnificently'),K('magnificently'),O('magnificently')]),
E('magnificence','英、美 /mæɡˈnɪfɪsəns/','壮丽；华美；宏伟气派','把让人赞叹的气派当成整体来谈：宫殿的恢宏、山川的壮美，或盛大场面的华丽。','经古法语 magnificence 借自拉丁 magnificentia，接 magnificus“大气、壮丽”。英语名词有独立借入史，记录也较早；不是必须先有英语 magnificent 再把 -ent 改为 -ence。',G+[['拉丁 magnificentia → 古法语 magnificence','壮丽、气派、慷慨高贵'],['英语 magnificence','宏伟壮丽或华美的特质']],'the magnificence of the landscape 是景色整体的壮美。通常作为不可数名词说一种气派，不是数出“三个壮丽”；想数具体建筑、作品，需要另用名词。','the magnificence of a palace；in all its magnificence；natural magnificence。','size 问有多大；magnificence 是对壮丽气派的评价。magnification 是放大动作或倍率，和这个词只差几个音，却不是同一意思。',('No photograph fully captures the magnificence of the canyon.','没有哪张照片能完整呈现峡谷的壮美。'),('Visitors paused to admire the magnificence of the entrance hall.','参观者停下来欣赏入口大厅的恢宏气派。'),sources=[S('magnificence'),K('magnificence'),O('magnificence')]),
E('magnify','英、美 /ˈmæɡnɪfaɪ/','放大；夸大；增强某种影响','像拿放大镜一样，让本来小的东西显得更大。移到事情上，就是让一个问题、缺点或影响变得更突出。','经法语 magnefiier／magnifier 借自拉丁 magnificare。现代可认出 magn- 与 -ify“使成……”；完整历史却是借入动词，再在英语中发展出光学放大的用法。',V,'A lens magnifies an image 说图像看起来变大，物体本身没长大。Public attention magnifies a mistake 则是关注把错误的影响放大。较旧或宗教语境还有“颂扬”的用法。','magnify an image；magnify a problem；magnify the effect；a magnifying glass。','enlarge 可以把实际尺寸做大，也可放大图像；magnify 特别自然地说借光学、显示或关注使某物显得更大。exaggerate 明确偏夸大，magnify 也能中性使用。',('This lens magnifies the tiny scratches on the surface.','这枚镜片把表面细小的划痕放大了。'),('Repeated rumours can magnify a minor disagreement.','反复传播的传言会把小小的分歧放大。'),sources=[S('magnify'),K('magnify'),O('magnify')]),
E('magnified','英、美 /ˈmæɡnɪfaɪd/','放大了的；被放大的；夸大了','本来难看清的细节被拉大了，或者本来较小的影响因其他因素而加重了。','英语 magnify 的过去式、过去分词；辅音字母加 y 结尾，拼写改 y 为 i 再加 -ed。读音保留 /aɪ/，末尾 -ed 读 /d/。',V+[['英语 magnify → magnified','表示已经放大；也用于描述放大后的图像']],'a magnified image 是放大图；The effect was magnified 说效果或影响被增强。它不保证图像细节更多：把模糊图片放大，仍可能只是更大的模糊。','a magnified image；a magnified view；the effect was magnified。','magnified 说明放大；clearer 说明更清晰。两者常相伴，却不是一回事。',('The screen showed a magnified image of a single leaf.','屏幕显示出一片叶子的放大图。'),('The delay was magnified by poor communication between the teams.','团队之间沟通不畅，使延误变得更严重。'),sources=[K('magnified'),S('magnify'),O('magnify')]),
E('magnification','英、美 /ˌmæɡnɪfɪˈkeɪʃən/','放大；放大率；放大倍数','关注的是“放大的这件事”或“放到了原来的几倍”，像显微镜旁标出的倍率。','经法语 magnificacion 或直接借晚期拉丁 magnificatio／magnificationem，接 magnificare。现代对应 magnify 的名词，但拉丁、法语已有独立名词，不能把古词说成由现代英语倒造。',G+[['拉丁 magnificare → magnificatio／magnificationem','放大、颂扬 → 对应动作名词'],['古法语 magnificacion／直接拉丁借入 → 英语 magnification','放大过程；后来用于光学放大及倍率']],'at high magnification 是在高倍率下观察。更高倍率不总能看到更多真实细节，还取决于成像能分开多细的结构；所以 magnification 与 resolution 要区分。','at high magnification；under magnification；a magnification of ten times；increase the magnification。','magnification 是放大或倍率；magnificence 是壮丽、气派。resolution 是分辨细节的能力，不能直接当成倍率。',('The fibres become visible under magnification.','这些纤维放大后就看得见了。'),('The microscope offers several levels of magnification.','这台显微镜提供几档放大倍率。'),sources=[S('magnification'),K('magnification'),O('magnification')]),
E('magnifier','英 /ˈmæɡnɪfaɪə/；美 /ˈmæɡnɪfaɪər/','放大镜；放大工具','它的工作就是把小字、小细节变大给你看，可以是一枚镜片，也可以是屏幕上的软件工具。','英语 magnify + -er；-er 在这里可以指工具，不必是一个“负责放大的人”。拼写 magnify 的 y 改成 i，读音仍保留 /aɪ/。',V+[['英语 magnify + -er → magnifier','使东西显得更大的工具；后来也指屏幕放大功能']],'a handheld magnifier 是手持放大镜；a screen magnifier 是屏幕放大工具。这个词比 magnifying glass 更能覆盖电子工具，后者通常让人想到实体镜片。','a handheld magnifier；a screen magnifier；use a magnifier。','microscope 是显微镜这种具体仪器；magnifier 是更宽的放大工具名称。并非每个 magnifier 都是 microscope。',('She used a magnifier to read the tiny date on the coin.','她用放大镜看硬币上细小的年份。'),('The screen magnifier makes the menu easier to read.','屏幕放大工具让菜单更容易看清。'),sources=[S('magnifier'),K('magnifier'),O('magnifier')]),
E('magnitude','英 /ˈmæɡnɪtjuːd/；美 /ˈmæɡnɪtuːd/','大小；规模；程度；震级；星等','先问“有多大、多严重、多强”，暂时不问朝哪个方向。这可以说工作的规模，也可以成为科学里衡量大小的量。','来自拉丁 magnitudo，由 magnus“大”加表示性质、状态的 -tudo 构成。词虽然接“大”，现代 magnitude 也能是一个很小的大小数值。',[['拉丁 magnus + -tudo → magnitudo','大、伟大 → 大小、规模'],['中古英语 magnitude','大小、程度；后发展出不同学科的量度名称']],'the magnitude of a problem 是问题的规模；向量的 magnitude 是长度，不带方向。地震中 magnitude 是震级，概括地震自身大小，不等于某地感受到的烈度。天文的 magnitude 是星等，数值越小表示越亮，不能按“大数一定更亮”理解。','the magnitude of the task；a magnitude 5 earthquake；an order of magnitude。','size 很日常；magnitude 更适合抽象规模或专业量度。order of magnitude 是数量级，比较时通常一档对应十倍，不是“大约差一点”。',('We did not understand the magnitude of the task until work began.','工作开始后，我们才明白这项任务规模有多大。'),('The report gives the earthquake’s magnitude and maps the shaking in different towns.','报告给出了地震震级，并标示了不同城镇的震动情况。'),('The vector has a magnitude of five, regardless of how it is drawn on the page.','这个向量的大小是五，不受它在纸上如何示意绘制的影响。'),sources=[S('magnitude'),O('magnitude'),'https://www.usgs.gov/programs/earthquake-hazards/earthquake-magnitude-energy-release-and-shaking-intensity','https://science.nasa.gov/solar-system/skywatching/night-sky-network/check-your-sky-quality-with-orion/']),
E('magnate','英、美 /ˈmæɡneɪt/','商业巨头；大亨；权贵','在某个行业里，拥有庞大企业、财富和影响力的“大人物”。大的不是身材，而是掌握的资源与分量。','借自晚期拉丁 magnates，原为 magnas“大人物、贵族”的复数，接 magnus“大”。英语把它用作单数 magnate，再按英语规则组成 magnates。',[['拉丁 magnus → 晚期拉丁 magnas；复数 magnates','伟大、有分量 → 大人物、贵族'],['中古英语 magnate','权贵；现代常指实力雄厚的工商界人物']],'an oil magnate 是石油业大亨；a media magnate 是传媒巨头。这个词告诉你财富和影响力很大，不自动表示此人品德伟大。','a media magnate；an oil magnate；a property magnate；a business magnate。','magnet 是磁铁，来自另一套名称；magnate 是大亨。tycoon 与 magnate 很接近，都常指工商巨头。',('The media magnate bought several regional newspapers.','这位传媒大亨收购了几家地方报纸。'),('The museum was funded by a shipping magnate.','这座博物馆由一位航运业巨头出资兴建。'),sources=[S('magnate'),K('magnate'),O('magnate')]),
E('magnum','英、美 /ˈmæɡnəm/','大瓶装酒；大威力弹药或相应枪械；见于“巨著”拉丁短语','从“大号”来记：酒瓶是大瓶装，另一些专门名称用它强调规格或威力。遇到 magnum opus，则是在说一个人的大作品、代表作。','直接接拉丁 magnus“大”的中性单数形式 magnum。英语酒瓶名称是名词化用法；枪弹名称是后来的命名用法；magnum opus 保留拉丁形容词与 opus“作品”的搭配。',[['拉丁 magnus；中性形式 magnum','大的、伟大的；拉丁短语 magnum opus 指伟大的作品'],['英语中的不同用法','magnum 名词用于大瓶酒，后来也用于枪弹名称；magnum opus 则保留拉丁短语表示代表作']],'现代葡萄酒计量中，a magnum 通常为 1.5 升，相当于两瓶常见的 750 毫升装。magnum opus 可形容一位作家、音乐家或学者最重要的作品。枪弹义见于小说、新闻等，不等于所有大尺寸枪械都如此命名。','a magnum of champagne；a magnum bottle；someone’s magnum opus。','magnum 是拉丁形式留下的具体名称；magnitude 是大小、规模。magnum opus 中 opus 是作品，不是职业 occupation 的缩写。',('A magnum of champagne stood in the centre of the table.','桌子中央放着一大瓶香槟。'),('The historian regarded the three-volume study as her magnum opus.','这位历史学家把那部三卷本研究著作视为自己的代表作。'),sources=[S('magnum'),K('magnum'),O('magnum')]),
E('magnanimously','英、美 /mæɡˈnænɪməsli/','宽宏大量地；大度地','本来可以计较、羞辱对手或只顾自己，却选择放宽心胸，给对方体面或机会。','英语 magnanimous + -ly。magnanimous 的背景是拉丁 magnus“大”+ animus“心、精神”组成 magnanimus；英语也有从 magnanimity 配成形容词的分析。副词继承的是“大气度”，不是身体变大。',[['拉丁 magnus + animus → magnanimus','大 + 心胸、精神 → 气量大的'],['英语 magnanimous','可从拉丁借入，也有依 magnanimity 构词的分析'],['magnanimous + -ly → magnanimously','宽宏大量地处理事情']],'magnanimously congratulate a rival 是大度地祝贺对手。词往往带赞赏，但如果一个人自称自己“宽宏大量地允许别人……”，语境也可能让它显得居高临下。','magnanimously accept an apology；magnanimously congratulate a rival；magnanimously offer。','generously 可说给钱、给时间很慷慨；magnanimously 更突出面对得失、冲突或对手时不狭隘计较。',('She magnanimously congratulated the colleague who won the award.','她大度地祝贺了那位获奖的同事。'),('He magnanimously accepted the apology and suggested a fresh start.','他宽宏大量地接受了道歉，并提议重新开始。'),sources=[S('magnanimous'),K('magnanimously'),O('magnanimously')]),
]
ROOT=dict(id='C0698',meaning='大；伟大；规模、气派或气量大',core='拉丁 magnus 的大不只指体积。东西显得大是 magnify，问大小与规模是 magnitude，做得出色是 magnificent，心胸大是 magnanimous。',image='magnus 大 → magnificus 做大事、壮丽 → magnificent／magnify；magnitudo 大小 → magnitude；magnas 大人物 → magnate；magnus + animus 心胸 → magnanimous。',intro='把这组词想成几把不同的尺子：物体用尺寸量，任务用规模量，表现用赞叹来评价，人待人接物则看气量。它们同接“大”，但每个词的现代用法各有重点。',forms='magnification、magnificence 有自己的法语／拉丁名词路线；magnify 也是借入词，不是英语临时把 magn- 与 -ify 拼在一起。magnified、magnifier 可按英语构词理解。magnum 是 magnus 的拉丁中性形式。',branches=[['令人赞叹的气派或表现','magnificent, magnificently, magnificence'],['使细节或影响显得更大','magnify, magnified, magnification, magnifier'],['量出规模与大小','magnitude'],['大人物和大规格名称','magnate, magnum'],['胸襟、气度大','magnanimous, magnanimity, magnanimously']],contrasts='magnate 大亨与 magnet 磁铁不同源。magnification 是放大，magnificence 是壮丽。magnitude 用在天文星等时，数值小反而更亮，不要用根义替代专业定义。',practice='A magnifier makes print look bigger; a magnanimous person makes room for others. 放大镜让字显得大，宽宏的人则给别人留出空间。',words=[],exclude={})
